export class ApiError extends Error {
  status: number;
  data: any;

  constructor(message: string, status: number, data?: any) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.data = data;
  }
}

export const API_BASE_URL = (
  process.env.NEXT_PUBLIC_API_URL ||
  process.env.NEXT_PUBLIC_API_BASE_URL ||
  'http://localhost:8000'
).replace(/\/$/, '');

function getStoredToken(): string | null {
  if (typeof window === 'undefined') return null;

  const localToken = localStorage.getItem('token') || localStorage.getItem('access_token');
  if (localToken) return localToken;

  const match = document.cookie.match(new RegExp('(^| )token=([^;]+)'));
  if (match) return match[2];

  return null;
}

export async function api(endpoint: string, options: RequestInit & { body?: any } = {}) {
  const headers = new Headers(options.headers || {});

  const token = getStoredToken();
  if (token && !headers.has('Authorization')) {
    headers.set('Authorization', `Bearer ${token}`);
  }

  let body = options.body;
  if (body && !(body instanceof FormData)) {
    if (!headers.has('Content-Type')) {
      headers.set('Content-Type', 'application/json');
    }
    if (typeof body === 'object') {
      body = JSON.stringify(body);
    }
  }

  const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
  const fullUrl = endpoint.startsWith('http') ? endpoint : `${API_BASE_URL}${cleanEndpoint}`;

  try {
    const response = await fetch(fullUrl, {
      ...options,
      headers,
      body,
    });

    if (response.status === 401) {
      if (typeof window !== 'undefined') {
        localStorage.removeItem('token');
        localStorage.removeItem('access_token');
        document.cookie = 'token=; path=/; max-age=0;';

        if (!window.location.pathname.startsWith('/login')) {
          window.location.href = '/login';
        }
      }
    }

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));

      let errorMessage = 'Không thể thực hiện yêu cầu';
      if (typeof errorData.detail === 'string') {
        errorMessage = errorData.detail;
      } else if (Array.isArray(errorData.detail)) {
        errorMessage = errorData.detail
          .map((e: any) => `${e.loc ? e.loc[e.loc.length - 1] + ': ' : ''}${e.msg}`)
          .join(', ');
      } else if (errorData.message) {
        errorMessage = errorData.message;
      }

      throw new ApiError(errorMessage, response.status, errorData);
    }

    if (response.status === 204) return null;
    return await response.json();

  } catch (error) {
    if (error instanceof ApiError) throw error;
    throw new ApiError(
      error instanceof Error ? error.message : 'Không thể kết nối đến máy chủ Backend',
      500
    );
  }
}

export async function fetcher(url: string) {
  return api(url, { method: 'GET' });
}

export async function checkHealth() {
  try {
    return await api('/health');
  } catch {
    try {
      return await api('/');
    } catch {
      return null;
    }
  }
}